// 1. Define mixin
@mixin flex-center {
  display: flex;
  justify-content: center;
  align-items: center;
}

// 2. Include mixin
.modal-backdrop {
  position: fixed;
  inset: 0;
  background-color: rgba(0, 0, 0, 0.5);

  @include flex-center;
}

@mixin square($size) {
  width: $size;
  height: $size;
}

.avatar-icon {
  @include square(48px);
  border-radius: 50%;
}

.thumbnail-box {
  @include square(120px);
}

@mixin custom-shadow($x: 0, $y: 4px, $blur: 10px, $spread: 0, $color: rgba(0, 0, 0, 0.1)) {
  box-shadow: $x $y $blur $spread $color;
}

// Using default arguments
.card-standard {
  @include custom-shadow;
}

// Overriding specific arguments
.card-elevated {
  @include custom-shadow(0, 10px, 25px, -5px, rgba(0, 0, 0, 0.2));
}

@mixin button-theme($bg-color: #f3f4f6, $text-color: #111827, $border-color: #d1d5db) {
  background-color: $bg-color;
  color: $text-color;
  border: 1px solid $border-color;
}

.btn-outline {
  // Pass ONLY the border-color by explicitly naming the argument
  @include button-theme($border-color: #3b82f6);
}

@mixin for-tablet {
  @media (min-width: 768px) {
    @content; // Injects the block passed into the @include
  }
}

.sidebar {
  width: 100%;

  @include for-tablet {
    width: 280px;
    display: block;
  }
}

@use 'sass:math';

// Custom function computes and returns a calculated value
@function rem-calc($px-value, $base-size: 16px) {
  @if not math.is-unitless($px-value) and math.unit($px-value) != 'px' {
    @error "Argument must be in pixels, received #{$px-value}";
  }

  @return math.div($px-value, $base-size) * 1rem;
}

.hero-headline {
  font-size: rem-calc(32px); // Compiles to 2rem
  margin-bottom: rem-calc(16px); // Compiles to 1rem
}
